#!/bin/bash
#
# Single source of truth for the Helm chart versions, derived from the
# workflow env (VERSION=X.Y.Z, DOCKERREVISION=N):
#
#   version       = X.Y.Z-N             -> appVersion + image tags
#   chart_version = X.Y.(Z*1000 + N)    -> clean, strictly increasing SemVer
#                                          (2.21.6-9 => 2.21.6009), no --devel
#
# Usage:
#   helm-version.sh          print "version=..." and "chart_version=..."
#                            (suitable for >> "$GITHUB_OUTPUT")
#   helm-version.sh --check  fail if helm/Chart.yaml, helm/values.yaml or
#                            helm/README.md do not match these versions
#
# Requires yq (mikefarah v4 or the jq wrapper) for --check.

set -euo pipefail

: "${VERSION:?VERSION is not set}"
: "${DOCKERREVISION:?DOCKERREVISION is not set}"

if ! [[ "$VERSION" =~ ^([0-9]+)\.([0-9]+)\.([0-9]+)$ ]]; then
	echo "VERSION must be X.Y.Z, got '$VERSION'" >&2
	exit 1
fi
major=${BASH_REMATCH[1]} minor=${BASH_REMATCH[2]} patch=${BASH_REMATCH[3]}
if ! [[ "$DOCKERREVISION" =~ ^[0-9]+$ ]] || [ "$DOCKERREVISION" -ge 1000 ]; then
	echo "DOCKERREVISION must be an integer < 1000, got '$DOCKERREVISION'" >&2
	exit 1
fi

version="${VERSION}-${DOCKERREVISION}"
chart_version="${major}.${minor}.$((10#$patch * 1000 + 10#$DOCKERREVISION))"

if [ "${1:-}" != "--check" ]; then
	echo "version=${version}"
	echo "chart_version=${chart_version}"
	exit 0
fi

cd "$(dirname "$0")/../helm"
errors=0

expect() { # file, yq path, expected value
	local got
	got=$(yq -r "$2" "$1")
	if [ "$got" != "$3" ]; then
		echo "::error file=helm/$1::$2 is '$got', expected '$3'"
		errors=$((errors + 1))
	fi
}

expect Chart.yaml  .version               "$chart_version"
expect Chart.yaml  .appVersion            "$version"
expect values.yaml .manager.image.tag     "${version}-no-s6"
expect values.yaml .portal.image.tag      "${version}-no-s6-hiperf"
expect values.yaml .cronjob.image.tag     "${version}-no-s6"

# README.md is generated by helm-docs from the two files above
for s in "Version: ${chart_version}" "AppVersion: ${version}" \
	"\`\"${version}-no-s6\"\`" "\`\"${version}-no-s6-hiperf\"\`"; do
	if ! grep -qF "$s" README.md; then
		echo "::error file=helm/README.md::'$s' not found, regenerate it with helm-docs"
		errors=$((errors + 1))
	fi
done

if [ "$errors" -gt 0 ]; then
	echo "Helm chart is not aligned with ${version} (chart ${chart_version})." >&2
	exit 1
fi
echo "Helm chart aligned with ${version} (chart ${chart_version})."
